{%- assign sb_product = all_products['senson-s1-wellness-companion'] -%}

<style>
  .sb-section-pc {
    display: flex;
  }
  @media (max-width: 999px) {
    .sb-section-pc {
      display: none !importaxnt;
    }
  }
  @media (min-width: 1000px) {
    body {
      padding-bottom: 56px;
    }
  }

  /* 彩虹飘带背景 + 高透明度玻璃质感 */
  .sb-section-pc {
    background: linear-gradient(
      105deg,
      rgba(255, 80, 120, 0.45) 0%,
      rgba(255, 140, 0, 0.45) 14%,
      rgba(255, 210, 0, 0.45) 28%,
      rgba(60, 200, 60, 0.45) 42%,
      rgba(0, 180, 220, 0.45) 57%,
      rgba(130, 80, 220, 0.45) 71%,
      rgba(240, 80, 200, 0.45) 85%,
      rgba(255, 80, 120, 0.45) 100%
    );
    background-size: 200% auto;
    backdrop-filter: blur(16px) saturate(180%);
    -webkit-backdrop-filter: blur(16px) saturate(180%);
    box-shadow: 0 -2px 20px rgba(0, 0, 0, 0.1), inset 0 1px 1px rgba(255, 255, 255, 0.25);
    border-bottom: 1px solid rgba(255, 255, 255, 0.3) !important;
  }

  /* 彩虹缓慢飘移动画 */
  .sb-section-pc {
    animation: subtleRainbowShift 12s ease infinite;
  }
  @keyframes subtleRainbowShift {
    0% { background-position: 0% 50%; }
    50% { background-position: 100% 50%; }
    100% { background-position: 0% 50%; }
  }

  /* 文字阴影增强 */
  .sb-section-pc p,
  .sb-section-pc h3,
  .sb-section-pc h4,
  .sb-section-pc .pre-order-now,
  .sb-section-pc .pride-text {
    text-shadow: 0 2px 8px rgba(0, 0, 0, 0.4);
  }

  /* 按钮微调 */
  .sb-section-pc .button {
    transition: transform 0.2s ease, box-shadow 0.2s ease;
    background: #ffffffdd !important;
    backdrop-filter: blur(2px);
  }
  .sb-section-pc .button:hover {
    transform: scale(1.02);
    box-shadow: 0 4px 14px rgba(0, 0, 0, 0.25);
    background: #ffffffff !important;
  }

  /* 限时标签 */
  .sb-section-pc div[style*="background:#c84fb9"] {
    background: rgba(200, 79, 185, 0.85) !important;
    backdrop-filter: blur(4px);
    border-radius: 40px;
  }
</style>

<section
  class="sb-section-pc"
  id="sticky-bar-pc"
  style="position:fixed; bottom:0; left:0; z-index:999; width:100%; box-sizing:border-box; color:#fff; padding:8px 120px; align-items:center; justify-content:space-between; height:56px; display: flex; transition: opacity 0.35s cubic-bezier(0.2, 0.9, 0.4, 1.1); opacity: 0; pointer-events: none; border-bottom:1.277px solid rgba(255, 255, 255, 0.10);"
>
  <!-- 左侧：彩虹文案 + 产品标题（文案字体减小） -->
  <div style="display:flex; align-items:center; gap:16px; flex-wrap:wrap;">
    <span class="pride-text" style="font-size:18px; font-weight:600; line-height:1.2; white-space:normal;">Celebrate diversity and love. 🌈</span>
    <p style="margin:0; font-size:16px; font-weight:500;">{{ sb_product.title }}</p>
  </div>

  <div style="display:flex; align-items:center; gap:16px;">
    <div style="display:flex; align-items:center; gap:12px;">
      <div style="display:flex; padding:3px 8px; justify-content:center; align-items:center; gap:6px; background:#c84fb9; border-radius: 30px;">
        <span style="color:#fff; text-align:center; font-size:13px; font-weight:500; line-height:1.1;">Limited Time Price</span>
      </div>
      <div style="display:flex; gap:6px; align-items:center;">
        <h3 style="font-size:20px; font-weight:700; line-height:1.1; margin:0;">{{ sb_product.price | money }}</h3>
        {%- if sb_product.compare_at_price > sb_product.price -%}
          <h4 style="color:rgba(255,255,255,0.8); font-size:13px; font-weight:400; line-height:1; text-decoration-line:line-through; margin:0;">{{ sb_product.compare_at_price | money }}</h4>
        {%- endif -%}
      </div>
    </div>
    <a href="{{ sb_product.url }}" class="button" style="display:flex; padding:6px 28px; justify-content:center; align-items:center; gap:6px; text-decoration-line:none; text-transform:none; border-radius:1000px; background:#fff; transition: transform 0.2s ease;">
      <span class="pre-order-now" style="color:#000; text-align:center; font-size:18px; font-weight:500; line-height:1.2; text-transform:none;">Shop with Pride</span>
    </a>
  </div>
</section>

<script>
  (function() {
    var bar = document.getElementById('sticky-bar-pc');
    if (!bar) return;

    function isDesktop() { return window.innerWidth >= 1000; }

    var heroSelectors = ['.hero-area', '.hero', '[data-hero]', '.main-banner', '.shopify-section:first-child', '#shopify-section-template--hero'];
    var heroElement = null;
    function findHero() {
      for (var i = 0; i < heroSelectors.length; i++) {
        var el = document.querySelector(heroSelectors[i]);
        if (el) return el;
      }
      var sections = document.querySelectorAll('section, div[class*="hero"], div[class*="banner"]');
      for (var j = 0; j < sections.length; j++) {
        var sec = sections[j];
        var rect = sec.getBoundingClientRect();
        if (rect.height > window.innerHeight * 0.7 && sec.offsetTop < 100) return sec;
      }
      return null;
    }
    heroElement = findHero();

    var observer = new MutationObserver(function() {
      if (!heroElement) heroElement = findHero();
    });
    observer.observe(document.body, { childList: true, subtree: true });

    function shouldShow() {
      if (heroElement) {
        var rect = heroElement.getBoundingClientRect();
        return rect.bottom <= 0;
      } else {
        var scrollY = window.pageYOffset || document.documentElement.scrollTop;
        return scrollY > window.innerHeight * 0.95;
      }
    }

    var currentState = false;
    function updateVisibility() {
      if (!isDesktop()) {
        bar.style.opacity = '0';
        bar.style.pointerEvents = 'none';
        currentState = false;
        return;
      }
      var needShow = shouldShow();
      if (needShow && !currentState) {
        bar.style.opacity = '1';
        bar.style.pointerEvents = 'auto';
        currentState = true;
      } else if (!needShow && currentState) {
        bar.style.opacity = '0';
        bar.style.pointerEvents = 'none';
        currentState = false;
      }
    }

    var ticking = false;
    function handleScrollOrResize() {
      if (!ticking) {
        requestAnimationFrame(function() {
          updateVisibility();
          ticking = false;
        });
        ticking = true;
      }
    }

    window.addEventListener('scroll', handleScrollOrResize, { passive: true });
    window.addEventListener('resize', function() {
      updateVisibility();
      handleScrollOrResize();
    });

    if (document.readyState === 'loading') {
      document.addEventListener('DOMContentLoaded', updateVisibility);
    } else {
      updateVisibility();
    }
    window.addEventListener('load', function() { setTimeout(updateVisibility, 100); });
  })();
</script>

